from pathlib import Path
import subprocess,datetime,json,sys,hashlib
R=Path(__file__).parent;now=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat();start=now();cmd=['/workspace/browser-env/venv/bin/python',str(R/'remaining-author-collector.py')];p=subprocess.run(cmd,capture_output=True);(R/'remaining-author.stdout.log').write_bytes(p.stdout);(R/'remaining-author.stderr.log').write_bytes(p.stderr);(R/'remaining-author-external-process.json').write_text(json.dumps({'command':cmd,'startUTC':start,'endUTC':now(),'actualCollectorExit':p.returncode,'launcherWillPropagate':p.returncode,'stdoutSHA256':hashlib.sha256(p.stdout).hexdigest(),'stderrSHA256':hashlib.sha256(p.stderr).hexdigest()},indent=2));print(p.stdout.decode(),end='');print('actual collector exit',p.returncode,flush=True);sys.exit(p.returncode)
